/// <summary>
/// Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
/// This SO extract class is called from TO finalisation with some differences with the SO extract called from SO extract screen.
/// </summary>
class METSalesPickingListGenerationTaskService_CrossDock extends METSalesPickingListGenerationTaskServiceBase
{
    InventTransferId transferId;

}

Method.Source:
/// <summary>
/// Checks if sales line is eligible for cancellation.
/// Implementated in derived classes.
/// </summary>
/// <param name = "_salesTable">Sales table</param>
/// <param name = "_salesLine">Sales line</param>
/// <param name = "_pickListOrderedQty">Set to yes if picking list to be generated by ordered qty</param>
/// <returns>True if valid; otherwise, false.</returns>
protected boolean cancelSalesLine(SalesTable _salesTable, SalesLine _salesLine, boolean _pickListOrderedQty)
{
    METSalesLine metSalesLine;

    boolean ret = super(_salesTable, _salesLine, _pickListOrderedQty);

    if (ret && transferId)
    {
        metSalesLine = _salesLine.metSalesLine();

        ret = (metSalesLine.TransferOrderNumber == transferId);
    }

    return ret;
}

/// <summary>
/// Gets and sets related Transfer Id.
/// </summary>
/// <param name = "_transferId">Transfer Id</param>
/// <returns>Transfer Id</returns>
public InventTransferId parmTransferId(InventTransferId _transferId = transferId)
{
    transferId = _transferId;
    return transferId;
}

/// <summary>
/// Method with the condition to update the SalesParmLine
/// </summary>
/// <param name = "_salesLine"><c>SalesLine</c> record</param>
/// <returns>True</returns>
protected boolean updateSalesParmLineCondition(SalesLine _salesLine)
{
    // return true as the xDock SO will be marked as Extracted
    return true;
}

/// <summary>
/// Method to set the additional SalesParmLine fields when SO extract called from TO finalisation
/// </summary>
/// <param name = "_salesParmLine"><c>SalesParmLine</c> record</param>
/// <param name = "_salesLine"><c>SalesLine</c> record</param>
protected void setSalesParmLineFields(SalesParmLine _salesParmLine, SalesLine _salesLine)
{
    // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
    // DeliverNow is in salesUnit, reservedPhysical in ea. At TO finalisation, SO line reservation is updated with the TO receipt qty
    // which is already reflected when SalesParmLine are created
    //_salesParmLine.DeliverNow = _salesLine.reservedPhysical();
    InventDim inventDimLoc = _salesLine.inventDim();

    if (inventDimLoc.wMSLocationId == '')
    {
        inventDimLoc.wMSLocationId = inventDimLoc.inventLocation().DefaultFinalShipmentLocation;
        _salesParmLine.InventDimId = InventDim::findOrCreate(inventDimLoc).inventDimId;
    }
}

/// <summary>
/// Update the SO picking list with the TO picking list reference
/// </summary>
/// <param name = "_wmsPickingRoute">SO <c>WMSPickingRoute</c> record</param>
protected void updateWmsPickingRoute(WmsPickingRoute _wmsPickingRoute)
{
    wmsPickingRoute.selectForUpdate(true);
    wmsPickingRoute.METTransferOrderPickingRouteId = this.getTransferPickListReference(wmsPickingRoute);
    wmsPickingRoute.doUpdate();
}

/// <summary>
/// Get the corresponding TO picking list Id
/// </summary>
/// <param name = "_wmsPickingRoute">SO <c>WMSPickingRoute</c> record</param>
/// <returns>TO picking list Id</returns>
private WMSPickingRouteID getTransferPickListReference(WMSPickingRoute _wmsPickingRoute)
{
    SalesLine salesLine;
    WMSOrderTrans orderTrans;

    select firstonly orderTrans
        where orderTrans.shipmentId == _wmsPickingRoute.shipmentId
        && orderTrans.routeId == _wmsPickingRoute.pickingRouteID
        join salesLine
        where salesLine.InventTransId == orderTrans.inventTransId
        && salesLine.SalesId == orderTrans.inventTransRefId;

    WMSPickingRoute transferPickingRoute;

    if(salesLine)
    {
        METInventTransferLine metTransLine;
        InventTransferLine transferLine;

        select firstonly metTransLine
            where metTransLine.SalesLineTransId == salesLine.InventTransId
            join transferLine
            where transferLine.RecId == metTransLine.InventTransferLine;

        select firstonly transferPickingRoute
            where transferPickingRoute.transRefId == transferLine.TransferId
            && transferPickingRoute.transType == InventTransType::TransferOrderShip;

    }

    return transferPickingRoute.pickingRouteID;
}

/// <summary>
/// Do not trigger the PL business event when SO extract is triggered from TO finalisation
/// </summary>
/// <param name = "_wmsPickingRoute">><c>WMSPickingRoute</c> record</param>
protected void triggerBusinessEvent(WMSPickingRoute _wmsPickingRoute)
{
    // Do not trigger PL business event from TO finalisation as the picking list registration is automatically generated
}
